effect.shader:
// Shadertoy port: bind acTime as iTime and input size as iResolution

// Helpers and bindings
vec2 getResolution() {
  vec2 s = getTexSize(inputImg.size);
  // Fallback to 1920x1080 if size is zero (no content), to avoid div by zero
  if (s.x <= 0.0 || s.y <= 0.0) s = vec2(1920.0, 1080.0);
  return s;
}

// Sample env texture with equirectangular mapping from direction 
const float PI = 3.14159265358979323846; 
// GLSL ES 1.00 helper (some runtimes lack radians())
float deg2rad(float d){ return d * (PI / 180.0); }
vec2 dirToEquirect(vec3 d) {
  d = normalize(d);
  float phi = (abs(d.z) + abs(d.x) > 0.0) ? atan(d.z, d.x) : 0.0;
  float theta = acos(clamp(d.y, -1.0, 1.0));
  return vec2(phi / (2.0*PI) + 0.5, theta / PI);
}

// Shadertoy uniforms replacement
#define iTime acTime

// ---------------- Copied/Adapted from source ----------------
float localTime = 0.0;
float seed = 1.0;

float fade = 1.0;
vec3 sunDir;
vec3 sunCol;
float exposure = 1.0;
vec3 skyCol, horizonCol;

float marchCount = 0.0;

float v31(vec3 a){ return a.x + a.y * 37.0 + a.z * 521.0; }
float v21(vec2 a){ return a.x + a.y * 37.0; }
float Hash11(float a){ return fract(sin(a)*10403.9); }
float Hash21(vec2 uv){ float f = uv.x + uv.y * 37.0; return fract(sin(f)*104003.9); }
vec2 Hash22(vec2 uv){ float f = uv.x + uv.y * 37.0; return fract(cos(f)*vec2(10003.579, 37049.7)); }
vec2 Hash12(float f){ return fract(cos(f)*vec2(10003.579, 37049.7)); }
float Hash1d(float u){ return fract(sin(u)*143.9); }
float Hash2d(vec2 uv){ float f = uv.x + uv.y * 37.0; return fract(sin(f)*104003.9); }
float Hash3d(vec3 uv){ float f = uv.x + uv.y * 37.0 + uv.z * 521.0; return fract(sin(f)*110003.9); }
float mixP(float f0, float f1, float a){ return mix(f0, f1, a*a*(3.0-2.0*a)); }
const vec2 zeroOne = vec2(0.0, 1.0);
float noise2d(vec2 uv){ vec2 fr = fract(uv.xy); vec2 fl = floor(uv.xy); float h00 = Hash2d(fl); float h10 = Hash2d(fl + zeroOne.yx); float h01 = Hash2d(fl + zeroOne); float h11 = Hash2d(fl + zeroOne.yy); return mixP(mixP(h00, h10, fr.x), mixP(h01, h11, fr.x), fr.y); }
float noise(vec3 uv){ vec3 fr = fract(uv.xyz); vec3 fl = floor(uv.xyz); float h000 = Hash3d(fl); float h100 = Hash3d(fl + zeroOne.yxx); float h010 = Hash3d(fl + zeroOne.xyx); float h110 = Hash3d(fl + zeroOne.yyx); float h001 = Hash3d(fl + zeroOne.xxy); float h101 = Hash3d(fl + zeroOne.yxy); float h011 = Hash3d(fl + zeroOne.xyy); float h111 = Hash3d(fl + zeroOne.yyy); return mixP( mixP(mixP(h000, h100, fr.x), mixP(h010, h110, fr.x), fr.y), mixP(mixP(h001, h101, fr.x), mixP(h011, h111, fr.x), fr.y), fr.z); }

vec3 saturate(vec3 a) { return clamp(a, 0.0, 1.0); }
vec2 saturate(vec2 a) { return clamp(a, 0.0, 1.0); }
float saturate(float a) { return clamp(a, 0.0, 1.0); }

vec3 GetSunColorSmall(vec3 rayDir, vec3 sunDir){ vec3 localRay = normalize(rayDir); float dist = 1.0 - (dot(localRay, sunDir) * 0.5 + 0.5); float sunIntensity = 0.05 / dist; sunIntensity += exp(-dist*150.0)*7000.0; sunIntensity = min(sunIntensity, 40000.0); return sunCol * sunIntensity*0.025; }

vec3 GetEnvMap(vec3 rayDir, vec3 sunDir){ vec3 finalColor = mix(horizonCol, skyCol, pow(saturate(rayDir.y), 0.47))*0.95; float n = noise2d(rayDir.xz/max(0.0001,rayDir.y)*1.0); n += noise2d(rayDir.xz/max(0.0001,rayDir.y)*2.0)*0.5; n += noise2d(rayDir.xz/max(0.0001,rayDir.y)*4.0)*0.25; n += noise2d(rayDir.xz/max(0.0001,rayDir.y)*8.0)*0.125; n = pow(abs(n), 3.0); n = mix(n * 0.2, n, saturate(abs(rayDir.y * 8.0))); finalColor = mix(finalColor, (vec3(1.0)+sunCol*10.0)*0.75*saturate((rayDir.y+0.2)*5.0), saturate(n*0.125)); finalColor += GetSunColorSmall(rayDir, sunDir); return finalColor; }

vec3 GetEnvMapSkyline(vec3 rayDir, vec3 sunDir, float height){ vec3 finalColor = GetEnvMap(rayDir, sunDir); float radial = atan(rayDir.z, rayDir.x)*4.0; float skyline = floor((sin(5.3456*radial) + sin(1.234*radial)+ sin(2.177*radial))*0.6); radial *= 4.0; skyline += floor((sin(5.0*radial) + sin(1.234*radial)+ sin(2.177*radial))*0.6)*0.1; float mask = saturate((rayDir.y*8.0 - skyline-2.5+height)*24.0); float vert = sign(sin(radial*32.0))*0.5+0.5; float hor = sign(sin(rayDir.y*256.0))*0.5+0.5; mask = saturate(mask + (1.0-hor*vert)*0.05); finalColor = mix(finalColor * vec3(0.1,0.07,0.05), finalColor, mask); return finalColor; }

vec2 matmin(vec2 a, vec2 b){ if (a.x < b.x) return a; else return b; }

float sdBox(vec3 p, vec3 radius){ vec3 dist = abs(p) - radius; return min(max(dist.x, max(dist.y, dist.z)), 0.0) + length(max(dist, 0.0)); }
float cylCap(vec3 p, float r, float lenRad){ float a = length(p.xy) - r; a = max(a, abs(p.z) - lenRad); return a; }
float smin(float a, float b, float k){ return log2(exp2(k*a)+exp2(k*b))/k; }
float Repeat(float a, float len){ return mod(a, len) - 0.5 * len; }

vec2 Car(vec3 baseCenter, float unique){ float car = sdBox(baseCenter + vec3(0.0, -0.008, 0.001), vec3(0.01, 0.00225, 0.0275)); car = smin(car, sdBox(baseCenter + vec3(0.0, -0.016, 0.008), vec3(0.005, 0.0005, 0.01)), -160.0); vec3 wMirror = baseCenter + vec3(0.0, -0.005, 0.0); wMirror.z = abs(wMirror.z)-0.02; float wheels = cylCap((wMirror).zyx, 0.004, 0.0135); vec2 distAndMat = vec2(wheels, 3.0); distAndMat = matmin(distAndMat, vec2(car, 100000.0 + unique)); return distAndMat; }

float voxelPad = 0.2;
vec2 CityBlock(vec3 p, vec2 pint){ vec4 rand; rand.xy = Hash22(pint); rand.zw = Hash22(rand.xy); vec2 rand2 = Hash22(rand.zw); float baseRad = 0.2 + (rand.x) * 0.1; baseRad = floor(baseRad * 20.0+0.5)/20.0; vec3 baseCenter = p - vec3(0.5, 0.0, 0.5); float height = rand.w*rand.z + 0.1; float downtown = saturate(4.0 / length(pint.xy)); height *= downtown; height *= 1.5+(baseRad-0.15)*20.0; height += 0.1; height = floor(height*20.0)*0.05; float d = sdBox(baseCenter, vec3(baseRad, height, baseRad)); d = min(d, p.y); float height2 = max(0.0, rand.y * 2.0 - 1.0) * downtown; height2 = floor(height2*20.0)*0.05; rand2 = floor(rand2*20.0)*0.05; d = min(d, sdBox(baseCenter - vec3(0.0, height, 0.0), vec3(baseRad, height2 - rand2.y, baseRad*0.4))); d = min(d, sdBox(baseCenter - vec3(0.0, height, 0.0), vec3(baseRad*0.4, height2 - rand2.x, baseRad))); if (rand2.y > 0.25){ d = min(d, sdBox(baseCenter - vec3(0.0, height, 0.0), vec3(baseRad*0.8, height2, baseRad*0.8))); float topWidth = baseRad; if (height2 > 0.0) topWidth = baseRad * 0.8; d = max(d, -sdBox(baseCenter - vec3(0.0, height+height2, 0.0), vec3(topWidth-0.0125, 0.015, topWidth-0.0125))); }
else { if (height2 > 0.0) d = min(d, cylCap((baseCenter - vec3(0.0, height, 0.0)).xzy, baseRad*0.8, height2)); }
d = min(d, sdBox(baseCenter - vec3((rand.x-0.5)*baseRad, height+height2, (rand.y-0.5)*baseRad), vec3(baseRad*0.3*rand.z, 0.1*rand2.y, baseRad*0.3*rand2.x+0.025)));
vec3 boxPos = baseCenter - vec3((rand2.x-0.5)*baseRad, height+height2, (rand2.y-0.5)*baseRad); float big = sign(boxPos.x); boxPos.x = abs(boxPos.x)-0.02 - baseRad*0.3*rand.w; d = min(d, sdBox(boxPos, vec3(baseRad*0.3*rand.w, 0.07*rand.y, baseRad*0.2*rand.x + big*0.025)));
if (rand.y < 0.04){ d = min(d, length(baseCenter - vec3(0.0, height, 0.0)) - baseRad*0.8); }
vec2 distAndMat = vec2(d, 0.0); distAndMat = matmin(distAndMat, vec2(sdBox(baseCenter, vec3(0.35, 0.005, 0.35)), 1.0)); return distAndMat; }

vec2 DistanceToObject(vec3 p){ vec3 rep = p; rep.xz = fract(p.xz); vec2 distAndMat = CityBlock(rep, floor(p.xz)); vec3 p2 = p; rep.xyz = p2; float carTime = localTime*0.2; float crossStreet = 1.0; float repeatDist = 0.25; if (abs(fract(rep.x)-0.5) < 0.35){ p2.x += 0.05; p2.xz = p2.zx * vec2(-1.0,1.0); rep.xz = p2.xz; crossStreet = 0.0; repeatDist = 0.1; }
  rep.z += floor(p2.x); rep.x = Repeat(p2.x - 0.5, 1.0); rep.z = rep.z*sign(rep.x); rep.x = (rep.x*sign(rep.x))-0.09; rep.z -= carTime * crossStreet; float uniqueID = floor(rep.z/repeatDist); rep.z = Repeat(rep.z, repeatDist); rep.x += (Hash11(uniqueID)*0.075-0.01); float frontBack = Hash11(uniqueID*0.987)*0.18-0.09; frontBack *= sin(localTime*2.0 + uniqueID); rep.z += frontBack * crossStreet; vec2 carDist = Car(rep, uniqueID); distAndMat = matmin(distAndMat, carDist); return distAndMat; }

void CalcWindows(vec2 block, vec3 pos, inout vec3 texColor, inout float windowRef, inout vec3 normal){ vec3 hue = vec3(Hash21(block)*0.8, Hash21(block*7.89)*0.4, Hash21(block*37.89)*0.5); texColor += hue*0.4; texColor *= 0.75; float window = 0.0; window = max(window, mix(0.2, 1.0, floor(fract(pos.y*20.0-0.35)*2.0+0.1))); if (pos.y < 0.05) window = 1.0; float winWidth = Hash21(block*4.321)*2.0; if ((winWidth < 1.3) && (winWidth >= 1.0)) winWidth = 1.3; window = max(window, mix(0.2, 1.0, floor(fract(pos.x * 40.0+0.05)*winWidth))); window = max(window, mix(0.2, 1.0, floor(fract(pos.z * 40.0+0.05)*winWidth))); if (window < 0.5){ windowRef += 1.0; } window *= Hash21(block*1.123); texColor *= window; float wave = floor(sin((pos.y*40.0-0.1)*PI)*0.505-0.5)+1.0; normal.y -= max(-1.0, min(1.0, -wave*0.5)); float pits = min(1.0, abs(sin((pos.z*80.0)*PI))*4.0)-1.0; normal.z += pits*0.25; pits = min(1.0, abs(sin((pos.x*80.0)*PI))*4.0)-1.0; normal.x += pits*0.25; }

// Rotation helpers
mat3 rotX(float a){ float c=cos(a), s=sin(a); return mat3(1,0,0, 0,c,-s, 0,s,c); }
mat3 rotY(float a){ float c=cos(a), s=sin(a); return mat3(c,0,s, 0,1,0, -s,0,c); }
mat3 rotZ(float a){ float c=cos(a), s=sin(a); return mat3(c,-s,0, s,c,0, 0,0,1); }

// Sample input content directly in [0,1] UV space (no screen mapping)
vec4 sampleLayer(vec2 uv){ return texture2D(inputImg.texture, uv); }

vec3 RayTrace(in vec2 fragCoord){
  marchCount = 0.0;
  sunCol = vec3(258.0, 248.0, 200.0) / 3555.0;
  sunDir = normalize(vec3(0.93, 1.0, 1.0));
  horizonCol = vec3(1.0, 0.95, 0.85)*0.9;
  skyCol = vec3(0.3,0.5,0.95);
  exposure = 1.0;
  fade = 1.0;

  vec3 camPos, camUp, camLookat;
  vec2 iResolution = getResolution();
  vec2 uv = fragCoord.xy/iResolution.xy * 2.0 - 1.0;
  uv /= 2.0;

  // Param-driven camera (no automatic progression)
  camPos = vec3(camX, camY, camZ);
  float yaw = radians(yawDeg + (autoRotate ? acTime * rotateSpeed : 0.0));
  float pitch = radians(pitchDeg);
  vec3 forward = vec3(cos(pitch)*cos(yaw), sin(pitch), cos(pitch)*sin(yaw));
  camLookat = camPos + forward;
  camUp = vec3(0.0, 1.0, 0.0);

  vec3 camVec=normalize(camLookat - camPos);
  vec3 sideNorm=normalize(cross(camUp, camVec));
  vec3 upNorm=cross(camVec, sideNorm);
  vec3 worldFacing=(camPos + camVec);
  vec3 worldPix = worldFacing + uv.x * sideNorm * (iResolution.x/iResolution.y) + uv.y * upNorm;
  vec3 rayVec = normalize(worldPix - camPos);

  vec2 distAndMat; float t = 0.05; const float maxDepth = 45.0; vec3 pos = vec3(0.0); const float smallVal = 0.000625;
  // OPT: primary march capped at MARCH_STEPS (was 250). The step is still min(sdf, voxelBound), so it
  // can never overshoot the SDF; only the voxel *pad* is scaled with distance (0.2 near the camera ->
  // 0.74 at the 45-unit far plane) so the march still spans the full depth range inside the budget.
  // Mean step is ~0.53 + 0.012t, i.e. ~100 units of reach in 100 iterations against the 45 required;
  // the degenerate all-taps-zero case reaches 38 units and is caught by the fallback below.
  const int MARCH_STEPS = 100;
  float exhausted = 1.0;
  for (int i = 0; i < MARCH_STEPS; i++){
    pos = (camPos + rayVec * t); distAndMat = DistanceToObject(pos);
    float walk = distAndMat.x; float dx = -fract(pos.x); if (rayVec.x > 0.0) dx = fract(-pos.x); float dz = -fract(pos.z); if (rayVec.z > 0.0) dz = fract(-pos.z); float pad = voxelPad + t * 0.012; float nearestVoxel = min(fract(dx/rayVec.x), fract(dz/rayVec.z))+pad; nearestVoxel = max(pad, nearestVoxel); walk = min(walk, nearestVoxel); t += walk; if ((t > maxDepth) || (abs(distAndMat.x) < smallVal)) { exhausted = 0.0; break; } }
  // OPT: if the budget ran out while the ray was still in open air (or with the ground plane as the
  // nearest surface), hand it to the analytic sky/ground path below instead of shading a stale sample.
  if (exhausted > 0.5){ if ((distAndMat.x > 0.5) || (distAndMat.x >= pos.y - 0.004)) t = maxDepth + 1.0; }

  float alpha = -camPos.y / rayVec.y; if ((t > maxDepth) && (rayVec.y < -0.0)) { pos.xz = camPos.xz + rayVec.xz * alpha; pos.y = -0.0; t = alpha; distAndMat.y = 0.0; distAndMat.x = 0.0; }
  // OPT: colour accumulation at mediump (ray position/direction/distance stay highp above)
  mediump vec3 finalColor = vec3(0.0);

  if ((t <= maxDepth) || (t == alpha)){
    float dist = distAndMat.x; vec3 smallVec = vec3(smallVal, 0, 0); vec3 normalU = vec3(dist - DistanceToObject(pos - smallVec.xyy).x, dist - DistanceToObject(pos - smallVec.yxy).x, dist - DistanceToObject(pos - smallVec.yyx).x); vec3 normal = (dot(normalU, normalU) > 1e-24) ? normalize(normalU) : vec3(0.0, 1.0, 0.0);
    // OPT: AO uses 4 SDF taps instead of 6 (same 0.0125..0.4 radius span, every other octave dropped).
    // The 4-tap product is renormalised with ^1.5 so self-similar occlusion reproduces the 6-tap value
    // exactly; pow(ambientS,0.5) folds into a single pow(aoP,0.75) that is then squared back for ambientS.
    float aoP = 1.0; aoP *= saturate(DistanceToObject(pos + normal * 0.0125).x*80.0); aoP *= saturate(DistanceToObject(pos + normal * 0.05).x*20.0); aoP *= saturate(DistanceToObject(pos + normal * 0.2).x*5.0); aoP *= saturate(DistanceToObject(pos + normal * 0.4).x*2.5);
    float aoPow = pow(aoP, 0.75); float ambientS = aoPow * aoPow; float ambient = max(0.025, aoPow); ambient = saturate(ambient);
    vec3 ref = reflect(rayVec, normal);
    // OPT: shadow march capped at SHADOW_STEPS (was 40). Minimum voxel step raised 0.2 -> 0.29 so the
    // 4.5-unit shadow ray length (16 * 0.29 = 4.64) is still fully covered inside the smaller budget.
    const int SHADOW_STEPS = 16;
    float sunShadow = 1.0; float iter = 0.01; vec3 nudgePos = pos + normal*0.002; for (int i = 0; i < SHADOW_STEPS; i++){ vec3 shadowPos = nudgePos + sunDir * iter; float tempDist = DistanceToObject(shadowPos).x; sunShadow *= saturate(tempDist*150.0); if (tempDist <= 0.0) break; float walk = tempDist; float dx = -fract(shadowPos.x); if (sunDir.x > 0.0) dx = fract(-shadowPos.x); float dz = -fract(shadowPos.z); if (sunDir.z > 0.0) dz = fract(-shadowPos.z); float nearestVoxel = min(fract(dx/sunDir.x), fract(dz/sunDir.z))+smallVal; nearestVoxel = max(0.29, nearestVoxel); walk = min(walk, nearestVoxel); iter += max(0.01, walk); if (iter > 4.5) break; }
    sunShadow = saturate(sunShadow);

    float n =0.0; n += noise(pos*32.0); n += noise(pos*64.0); n += noise(pos*128.0); n += noise(pos*256.0); n += noise(pos*512.0); n = mix(0.7, 0.95, n);

    vec2 block = floor(pos.xz); mediump vec3 texColor = vec3(0.95, 1.0, 1.0); texColor *= 0.8; float windowRef = 0.0;
    if ((normal.y < 0.1) && (distAndMat.y == 0.0)){
      vec3 colTemp = texColor; vec3 nTemp = vec3(0.0);
      CalcWindows(block, pos, colTemp, windowRef, nTemp);
      texColor = colTemp; windowRef *= 0.2; normal = normalize(normal + nTemp * 0.2);
    } else {
      float xroad = abs(fract(pos.x+0.5)-0.5); float zroad = abs(fract(pos.z+0.5)-0.5); float road = saturate((min(xroad, zroad)-0.143)*480.0); texColor *= 1.0-normal.y*0.95*Hash21(block*9.87)*road; texColor *= mix(0.1, 1.0, road);
      float yellowLine = saturate(1.0-(min(xroad, zroad)-0.002)*480.0); yellowLine *= saturate((min(xroad, zroad)-0.0005)*480.0); yellowLine *= saturate((xroad*xroad+zroad*zroad-0.05)*880.0); texColor = mix(texColor, vec3(1.0, 0.8, 0.3), yellowLine);
      float whiteLine = saturate(1.0-(min(xroad, zroad)-0.06)*480.0); whiteLine *= saturate((min(xroad, zroad)-0.056)*480.0); whiteLine *= saturate((xroad*xroad+zroad*zroad-0.05)*880.0); whiteLine *= saturate(1.0-(fract(zroad*8.0)-0.5)*280.0); whiteLine *= saturate(1.0-(fract(xroad*8.0)-0.5)*280.0); texColor = mix(texColor, vec3(0.5), whiteLine);
      whiteLine = saturate(1.0-(min(xroad, zroad)-0.11)*480.0); whiteLine *= saturate((min(xroad, zroad)-0.106)*480.0); whiteLine *= saturate((xroad*xroad+zroad*zroad-0.06)*880.0); texColor = mix(texColor, vec3(0.5), whiteLine);
      float crossWalk = saturate(1.0-(fract(xroad*40.0)-0.5)*280.0); crossWalk *= saturate((zroad-0.15)*880.0); crossWalk *= saturate((-zroad+0.21)*880.0)*(1.0-road); crossWalk *= n*n; texColor = mix(texColor, vec3(0.25), crossWalk);
      crossWalk = saturate(1.0-(fract(zroad*40.0)-0.5)*280.0); crossWalk *= saturate((xroad-0.15)*880.0); crossWalk *= saturate((-xroad+0.21)*880.0)*(1.0-road); crossWalk *= n*n; texColor = mix(texColor, vec3(0.25), crossWalk);
      float sidewalk = 1.0; vec2 blockSize = vec2(100.0); if (pos.y > 0.1) blockSize = vec2(10.0, 50.0); sidewalk *= saturate(abs(sin(pos.z*blockSize.x)*800.0/blockSize.x)); sidewalk *= saturate(abs(sin(pos.x*blockSize.y)*800.0/blockSize.y)); sidewalk = saturate(mix(0.7, 1.0, sidewalk)); sidewalk = saturate((1.0-road) + sidewalk); texColor *= sidewalk;
    }
    if (distAndMat.y == 3.0){ texColor = vec3(0.05); }
    texColor *= vec3(1.0)*n*0.05; texColor *= 0.7; texColor = saturate(texColor);
    float windowMask = 0.0; if (distAndMat.y >= 100.0){ texColor = vec3(Hash11(distAndMat.y)*1.0, Hash11(distAndMat.y*8.765), Hash11(distAndMat.y*17.731))*0.1; texColor = pow(abs(texColor), vec3(0.2)); texColor = max(vec3(0.25), texColor); texColor.z = min(texColor.y, texColor.z); texColor *= Hash11(distAndMat.y*0.789) * 0.15; windowMask = saturate( max(0.0, abs(pos.y - 0.0175)*3800.0)-10.0); vec2 dirNorm = (dot(normal.xz, normal.xz) > 1e-24) ? abs(normalize(normal.xz)) : vec2(1.0, 0.0); float pillars = saturate(1.0-max(dirNorm.x, dirNorm.y)); pillars = pow(max(0.0, pillars-0.15), 0.125); windowMask = max(windowMask, pillars); texColor *= windowMask; }

    mediump vec3 lightColor = vec3(100.0)*sunCol * saturate(dot(sunDir, normal)) * sunShadow; float ambientAvg = (ambient*3.0 + ambientS) * 0.25; lightColor += (skyCol * saturate(normal.y *0.5+0.5))*pow(ambientAvg, 0.35)*2.5; lightColor *= 4.0;
    finalColor = texColor * lightColor;
    if (distAndMat.y >= 100.0){ float yfade = max(0.01, min(1.0, ref.y*100.0)); vec2 envUV = dirToEquirect(ref); finalColor += GetEnvMapSkyline(ref, sunDir, pos.y-1.5)*0.3*yfade*max(0.4,sunShadow); finalColor += saturate(texture2DCv(envTex.texture, envUV).xyz-0.35)*0.15*max(0.2,sunShadow); }
    if (windowRef != 0.0){ finalColor *= mix(1.0, 0.6, windowRef); float yfade = max(0.01, min(1.0, ref.y*100.0)); vec2 envUV = dirToEquirect(ref); finalColor += GetEnvMapSkyline(ref, sunDir, pos.y-0.5)*0.6*yfade*max(0.6,sunShadow)*windowRef; finalColor += saturate(texture2DCv(envTex.texture, envUV).xyz-0.35)*0.15*max(0.25,sunShadow)*windowRef; }
    finalColor *= 0.9; vec3 rv2 = rayVec; rv2.y *= saturate(sign(rv2.y)); mediump vec3 fogColor = GetEnvMap(rv2, sunDir); fogColor = min(vec3(9.0), fogColor); finalColor = mix(fogColor, finalColor, exp(-t*0.02));
  } else {
    finalColor = GetEnvMap(rayVec, sunDir);
  }

  // ------------------------------------------------------------
  // Place input layer as a textured quad in the scene
  // placeLayer is an int uniform; use non-zero check for GLSL ES 1.00
  if (placeLayer != 0){
    // Build object transform
    float yaw = deg2rad(objYaw);
    float pitch = deg2rad(objPitch);
    float roll = deg2rad(objRoll);
    mat3 R = rotY(yaw) * rotX(pitch) * rotZ(roll);
    vec3 objPos = vec3(objPosX, objPosY, objPosZ);
    vec3 n = normalize(R * vec3(0.0, 1.0, 0.0)); // plane normal
    vec3 u = normalize(R * vec3(1.0, 0.0, 0.0)); // local X
    vec3 v = normalize(R * vec3(0.0, 0.0, 1.0)); // local Z

    float denom = dot(n, rayVec);
    if (abs(denom) > 1e-4){
      float tPlane = dot(n, (objPos - camPos)) / denom;
      if (tPlane > 0.0 && tPlane < maxDepth){
        // Is the plane hit closer than city geometry?
        float nearestT = t; if (nearestT > maxDepth) nearestT = maxDepth;
        if (tPlane < nearestT){
          vec3 hit = camPos + rayVec * tPlane;
          vec3 rel = hit - objPos;
          // Project into local axes
          float x = dot(rel, u);
          float z = dot(rel, v);
          float hw = 0.5 * objWidth * objScale;
          float hh = 0.5 * objHeight * objScale;
          if (abs(x) <= hw && abs(z) <= hh){
            vec2 tuv = vec2((x/hw)*0.5 + 0.5, (z/hh)*0.5 + 0.5);
            vec4 lay = sampleLayer(tuv);
            float a = lay.a * objOpacity;
            // Simple lambert with sun to sit in scene
            float lam = saturate(dot(n, sunDir))*0.25 + 0.75;
            vec3 layCol = lay.rgb * lam;
            // Composite over current finalColor
            finalColor = mix(finalColor, layCol, a);
          }
        }
      }
    }
  }

  finalColor *= vec3(1.0) * saturate(1.0 - length((fragCoord.xy/getResolution())/2.5)); finalColor *= 1.3*exposure; return vec3(clamp(finalColor, 0.0, 1.0)*saturate(fade+0.2));
}

void main(){
  vec2 res = getResolution();
  vec2 fragCoord = acScreenNorm * res;
  // Use user-controlled time so scene doesnt auto-progress
  localTime = time;
  vec3 finalColor = RayTrace(fragCoord);
  gl_FragColor = vec4(sqrt(clamp(finalColor, 0.0, 1.0)), 1.0);
}
